		//#endregion
		//#region src/client/index.ts
		/** 浏览器侧依赖；模块加载器会在这些服务就绪后调用 apply。 */
		const inject = [
			"slots",
			"connection",
			"locale"
		];
		/** agent_team_gui 使用的独立 Connection RPC channel。 */
		const RPC_CHANNEL = "/agent-team-gui";
		/** 将管理页和会话模式控件贡献到 dsh 的既有 additive slots。 */
		function apply(ctx) {
			const connection = ctx.get("connection");
			const locale = ctx.get("locale");
			const call = async (endpoint, payload, signal) => {
				const result = await connection.rpc.call(RPC_CHANNEL, endpoint, payload, signal);
				if (!result.ok) throw new Error(`${result.error.code}: ${result.error.message}`);
				return result.value;
			};
			ctx.effect(() => locale.register(AGENT_TEAM_LOCALE_NS, DICTIONARIES), "agent-team-gui: bilingual locale dictionary");
			const controller = new AgentTeamController(call, locale);
			ctx.effect(() => refreshAgentTeamsOnReconnect(controller, connection.hostDescription), "agent-team-gui: refresh durable teams after reconnect");
			ctx.effect(() => {
				const style = document.createElement("style");
				style.dataset.agentTeamGui = "true";
				style.textContent = CLIENT_STYLES;
				document.head.append(style);
				return () => {
					style.remove();
				};
			}, "agent-team-gui: theme-token styles");
			ctx.slots.inject("settings.section", () => ctx.slots.register({
				name: "settings.section",
				id: "agent-teams",
				order: 25,
				label: () => controller.i18n.t("teams"),
				inject: () => ({ controller })
			}, TeamSettingsPage));
			ctx.slots.inject("conversation.input.right", () => ctx.slots.register({
				name: "conversation.input.right",
				id: "agent-team-gui-mode",
				order: 80,
				inject: () => ({ controller })
			}, TeamComposerControl));
			ctx.slots.inject("conversation.input.dock", () => ctx.slots.register({
				name: "conversation.input.dock",
				id: "agent-team-run-dock",
				order: 15,
				inject: () => ({ controller })
			}, TeamRunDock));
			ctx.slots.inject("conversation.view", () => ctx.slots.register({
				name: "conversation.view",
				id: "agent-team-runs",
				order: 20,
				label: () => controller.i18n.t("runs"),
				inject: () => ({ controller })
			}, TeamRunCenter));
		}
		//#endregion
		exports.RPC_CHANNEL = RPC_CHANNEL;
		exports.apply = apply;
		exports.inject = inject;
		return module.exports;
